#include <cstdio>
#include <vector>
#include <queue>

using namespace std;

int main() {
    int S, T, P;
    if (scanf("%d %d %d", &S, &T, &P) != 3) return 0;

    vector<int> height(S + 1);
    for (int i = 1; i <= S; i++) scanf("%d", &height[i]);

    vector<vector<int>> adj(S + 1);
    for (int k = 0; k < T; k++) {
        int I, J;
        scanf("%d %d", &I, &J);
        if (height[I] > height[J]) adj[I].push_back(J);
        else if (height[J] > height[I]) adj[J].push_back(I);
    }

    vector<bool> visited(S + 1, false);
    queue<int> q;
    visited[P] = true;
    q.push(P);

    int reachable = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (size_t i = 0; i < adj[u].size(); i++) {
            int v = adj[u][i];
            if (!visited[v]) {
                visited[v] = true;
                reachable++;
                q.push(v);
            }
        }
    }

    printf("%d\n", reachable);
    return 0;
}
